contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        uint256 balAfter;
        uint256 supplyAfter;
        try c.withdraw(amount, false) {
            reverted = false;
            balAfter = c.balanceOf(address(this));
            supplyAfter = c.totalSupply();
